parameters.jsCode:
/**
 * Gemini Pitch Post-Processor & Enforcer
 * Strictly enforces Requirement 7: Exactly one sentence explaining why the user could be a valuable lead.
 */
const items = $input.all();
const originalItems = $('Normalize Profile Data').all();

return items.map((item, idx) => {
  const orig = originalItems[idx] ? originalItems[idx].json : {};
  const rawCandidate = item.json?.candidates?.[0]?.content?.parts?.[0]?.text || '';

  let cleaned = rawCandidate
    .replace(/^[\"'`\s]+|[\"'`\s]+$/g, '')
    .replace(/\*\*/g, '')
    .replace(/\n+/g, ' ')
    .replace(/^(Here is (why|the|a).*?:|Why they are a lead:|Lead analysis:|Reason:)\s*/i, '')
    .trim();

  // Extract strictly the first complete sentence
  const sentenceMatch = cleaned.match(/^([^.!?]+[.!?])/);
  if (sentenceMatch && sentenceMatch[1]) {
    cleaned = sentenceMatch[1].trim();
  } else if (cleaned.length > 0 && !/[.!?]$/.test(cleaned)) {
    cleaned += '.';
  }

  // Safe fallback if LLM response is empty or invalid
  if (!cleaned) {
    const title = orig.company && orig.company !== 'Not specified' ? `at ${orig.company}` : 'in the developer ecosystem';
    cleaned = `${orig.name || orig.login} is a high-impact engineer ${title} with ${orig.followers} followers and ${orig.public_repos} public repositories.`;
  }

  return {
    json: {
      ...orig,
      ai_pitch: cleaned
    }
  };
});
